// source: js/core/drafts.js
// ---- Small text-form draft recovery (no photos, files, signatures or secrets) ----
// Media remains in the server/upload flow; only ordinary fields are retained.
(function(){
  var page=(location.pathname.split('/').pop()||'').toLowerCase();
  if(page!=='dpr.html'&&page!=='pr-new.html')return;
  var key='vcms_draft_'+page, timer=null, suppress=false;
  function fields(){return Array.prototype.slice.call(document.querySelectorAll('input[id]:not([type=file]):not([type=password]),select[id],textarea[id]'));}
  function save(){
    var data={t:Date.now(),v:{}}; fields().forEach(function(el){if(el.id)data.v[el.id]=el.type==='checkbox'?!!el.checked:el.value;});
    try{localStorage.setItem(key,JSON.stringify(data));}catch(_){}
  }
  function restore(){
    var d;try{d=JSON.parse(localStorage.getItem(key)||'null');}catch(_){return}
    if(!d||!d.v)return; fields().forEach(function(el){if(Object.prototype.hasOwnProperty.call(d.v,el.id)){if(el.type==='checkbox')el.checked=!!d.v[el.id];else el.value=d.v[el.id];}});
    suppress=true; document.dispatchEvent(new Event('input',{bubbles:true}));setTimeout(function(){suppress=false},0);
    var b=document.getElementById('vmms-draft-banner');if(b)b.remove();
  }
  window.vmmsClearPageDraft=function(){try{localStorage.removeItem(key);}catch(_){}var b=document.getElementById('vmms-draft-banner');if(b)b.remove();};
  function offer(){
    var d;try{d=JSON.parse(localStorage.getItem(key)||'null');}catch(_){return}
    if(!d||!d.t||Date.now()-d.t>24*3600000)return;
    var b=document.createElement('div');b.id='vmms-draft-banner';b.style.cssText='position:fixed;left:12px;right:12px;bottom:calc(78px + env(safe-area-inset-bottom,0px));z-index:9998;background:#202631;color:#fff;border-radius:12px;padding:11px 13px;box-shadow:0 8px 24px rgba(0,0,0,.22);font:600 13px system-ui;display:flex;align-items:center;gap:10px';
    b.innerHTML='<span style="flex:1">An unfinished text draft is available.</span><button id="vmms-draft-restore" style="background:#C00000;color:#fff;border:0;border-radius:8px;padding:8px 10px;font-weight:800">Restore</button><button id="vmms-draft-discard" style="background:transparent;color:#fff;border:0;padding:7px">Discard</button>';
    document.body.appendChild(b);b.querySelector('#vmms-draft-restore').onclick=restore;b.querySelector('#vmms-draft-discard').onclick=window.vmmsClearPageDraft;
  }
  document.addEventListener('input',function(e){if(suppress||!(e.target&&e.target.id))return;clearTimeout(timer);timer=setTimeout(save,500);},true);
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(offer,1200)});else setTimeout(offer,1200);
})();


// source: js/core/pwa.js
// ---- PWA updater: show at most once per release and reload only after the
// new worker controls the page. This prevents iPhone's repeated update loop. ----
(function(){
  if(!('serviceWorker' in navigator))return;
  var RELEASE='20260825-ui2', seenKey='vcms_update_seen_'+RELEASE, reloading=false;
  function reloadOnce(){
    if(reloading)return;reloading=true;
    try{localStorage.setItem(seenKey,'1')}catch(_){}
    var b=document.getElementById('vmms-update');if(b)b.remove();
    var u=new URL(location.href);u.searchParams.set('_vcms',RELEASE);location.replace(u.toString());
  }
  window.addEventListener('load',function(){
    navigator.serviceWorker.register('sw.js?v='+RELEASE,{updateViaCache:'none'}).then(function(reg){
      navigator.serviceWorker.addEventListener('controllerchange',function(){
        if(document.getElementById('vmms-update'))reloadOnce();
      });
      reg.update().catch(function(){});
      reg.addEventListener('updatefound',function(){var nw=reg.installing;if(!nw)return;nw.addEventListener('statechange',function(){
        var seen=false;try{seen=localStorage.getItem(seenKey)==='1'}catch(_){}
        if(nw.state==='installed'&&navigator.serviceWorker.controller&&!seen&&!document.getElementById('vmms-update')){
          var b=document.createElement('button');b.id='vmms-update';b.textContent='VCMS update ready — tap once';b.style.cssText='position:fixed;left:12px;right:12px;bottom:calc(14px + env(safe-area-inset-bottom,0px));z-index:10001;border:0;border-radius:11px;background:#202631;color:#fff;padding:12px;font:800 13px system-ui;box-shadow:0 8px 24px rgba(0,0,0,.25)';
          b.onclick=function(){b.disabled=true;b.textContent='Updating VCMS…';try{localStorage.setItem(seenKey,'1')}catch(_){}if(reg.waiting)reg.waiting.postMessage({type:'SKIP_WAITING'});setTimeout(reloadOnce,900)};document.body.appendChild(b);
        }
      })});
    }).catch(function(){});
  });
})();


// source: js/core/layout.js
// ---- Desktop workspace standardisation (mobile markup and navigation untouched) ----
// Each operational page receives a stable page class. This lets directory, admin
// and report screens use the available laptop/monitor width without changing the
// familiar phone workflow used by supervisors.
(function () {
  var slug = (location.pathname.split("/").pop() || "home.html").replace(/\.html$/i, "").replace(/[^a-z0-9-]/gi, "");
  function tag(){ if(document.body) document.body.classList.add("vmms-page-" + slug); }
  if(document.body) tag(); else document.addEventListener("DOMContentLoaded",tag);
  var s=document.createElement("style"); s.id="vmms-desktop-workspaces";
  s.textContent=`
  @media screen and (min-width:900px){
    body[class*="vmms-page-"] main{width:calc(100% - 40px);max-width:1480px;margin-left:auto;margin-right:auto}
    body.vmms-page-workers main,body.vmms-page-sites main,body.vmms-page-users main,
    body.vmms-page-whatsapp main,body.vmms-page-reports main,body.vmms-page-manhours main,
    body.vmms-page-dprlist main,body.vmms-page-pr-directory main,body.vmms-page-settings main{
      max-width:none!important;width:100%!important;padding:20px 24px 70px!important
    }
    body.vmms-page-sites #list{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px!important}
    body.vmms-page-sites #list>*{margin:0!important;min-width:0}
    body.vmms-page-users main>div,body.vmms-page-pr-directory main>div,body.vmms-page-dprlist main>div,
    body.vmms-page-reports main>div,body.vmms-page-manhours main>div,body.vmms-page-settings main>div{
      border-color:#dce1e8!important;box-shadow:0 7px 20px rgba(15,23,42,.07)!important
    }
    body.vmms-page-whatsapp main{max-width:1100px!important;margin-left:auto!important;margin-right:auto!important}
    body.vmms-page-whatsapp #msg{min-height:420px;font-size:14px;line-height:1.65}
    body.vmms-page-dprlist table,body.vmms-page-pr-directory table,
    body.vmms-page-reports table,body.vmms-page-manhours table{width:100%}
  }
  @media screen and (min-width:1500px){
    body[class*="vmms-page-"] main{max-width:none}
    body.vmms-page-workers #list,body.vmms-page-sites #list{grid-template-columns:repeat(4,minmax(0,1fr))}
  }`;
  (document.head||document.documentElement).appendChild(s);
})();

// ---- Light global polish (safe, non-breaking): crisper type + nicer scrollbars ----
(function () {
  if (document.getElementById("vcms-polish")) return;
  var s = document.createElement("style"); s.id = "vcms-polish";
  s.textContent =
    "html{-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;text-rendering:optimizeLegibility;}" +
    "@media(min-width:1024px){::-webkit-scrollbar{width:10px;height:10px}" +
    "::-webkit-scrollbar-thumb{background:#CBD5E1;border-radius:8px}" +
    "::-webkit-scrollbar-thumb:hover{background:#94A3B8}" +
    "body:not(.shell){background:#E4E7EC !important}" +
    // Use the empty desktop gutters: widen phone-width content containers to ~1024px.
    // Excludes bottom-sheet modals (rounded-t-2xl) and pages that already opted into a
    // wider desktop width (md:max-w-*). Login stays narrow (uses max-w-sm).
    "[class~=\"max-w-md\"]:not([class*=\"md:max-w\"]):not([class*=\"rounded-t-2xl\"])" +
    "{max-width:64rem !important;}}";
  (document.head || document.documentElement).appendChild(s);
})();

